using System;
using System.Collections.Generic;

namespace ElectronicsShop.Models
{
   
    public class PurchaseTransaction
    {
        // PRIMARY KEY — auto-generated by SQL IDENTITY(1001,1)
        public int PurchaseID { get; set; }

        // DATE — when the purchase order was created
        public DateTime PurchaseDate { get; set; }

        // TEXT fields
        public string BuyerName { get; set; }
        public string SupplierName { get; set; }

        // NUMERIC charges (always decimal for financial values)
        public decimal DeliveryCharge { get; set; }
        public decimal TaxAmount { get; set; }
        public decimal Discount { get; set; }

        // CALCULATED total — stored in DB for reporting, computed in C# before saving
        public decimal GrandTotal { get; set; }

        // BOOLEAN — whether the invoice has been paid
        public bool IsPaid { get; set; }

        // IMAGE — stored as binary bytes in VARBINARY(MAX) column
        // null when no image uploaded
        public byte[] InvoiceImage { get; set; }

        // NAVIGATION PROPERTY — the child items list
        // Initialized as empty list so we never get NullReferenceException
        public List<PurchaseItem> Items { get; set; } = new List<PurchaseItem>();
    }
}
